#!/usr/bin/env bash
# usage: sample.sh <pid> <interval_s> <count> <out.tsv>  — aggregates only
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'docs/spikes/memory-baseline/sample.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'sample.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
for _a in "$@"; do case "$_a" in --help|-h)
  printf 'usage: %s %s\n' "${0##*/}" '<pid> <interval_s> <count> <out.tsv>'
  awk 'NR>1 && /^#/ {sub(/^# ?/, ""); print; next} NR>1 {exit}' "$0"
  exit 0;; esac; done
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../../../scripts/lib/build-id.sh"
build_flags "${BASH_SOURCE[0]}" "$@"

pid=$1; iv=$2; n=$3; out=$4
printf 't_s\trss_kb\tpss_anon_kb\tpss_file_kb\thwm_kb\tthreads\theap_kb\tarena_kb\tother_anon_kb\n' > "$out"
t0=$(date +%s)
for ((i=0;i<n;i++)); do
  [ -r /proc/$pid/smaps_rollup ] || break
  r=$(awk '/^Rss:/{r=$2}/^Pss_Anon:/{a=$2}/^Pss_File:/{f=$2}END{print r"\t"a"\t"f}' /proc/$pid/smaps_rollup)
  s=$(awk '/^VmHWM:/{h=$2}/^Threads:/{t=$2}END{print h"\t"t}' /proc/$pid/status)
  m=$(awk '/^[0-9a-f]+-[0-9a-f]+ /{name=$6; if(name=="")name="[anon]"} /^Size:/{sz=$2} /^Rss:/{ if(name=="[heap]")hp+=$2; else if(name=="[anon]"){ if(sz>=65000&&sz<=65540)ar+=$2; else an+=$2}} END{print hp+0"\t"ar+0"\t"an+0}' /proc/$pid/smaps)
  printf '%s\t%s\t%s\t%s\n' "$(( $(date +%s)-t0 ))" "$r" "$s" "$m" >> "$out"
  sleep "$iv"
done
